def img(p, w=1100, cap=''):
    im = Image.open(R + p).convert('RGB'); im.thumbnail((w, 2000)); b = io.BytesIO(); im.save(b, 'JPEG', quality=72)
    return '<figure><img src="data:image/jpeg;base64,%s">%s</figure>' % (base64.b64encode(b.getvalue()).decode(), ('<figcaption>%s</figcaption>' % cap) if cap else '')
